#include <bits/stdc++.h>
using namespace std;

const long long mod = 998244353;

long long fastExponentiation(long long base, long long exp) {
    long long result = 1;
    long long b = base % mod;
    long long e = exp;
    while (e > 0) {
        if (e & 1) {
            result = (result * b) % mod;
        }
        b = (b * b) % mod;
        e >>= 1;
    }
    return result;
}

long long modInverse(long long x) {
    return fastExponentiation(x, mod - 2);
}

long long readLong() {
    long long res = 0;
    bool neg = false;
    int c = getchar();
    while (c != EOF && (c < '0' || c > '9')) {
        if (c == '-') neg = true;
        c = getchar();
    }
    while (c >= '0' && c <= '9') {
        res = res * 10 + (c - '0');
        c = getchar();
    }
    return neg ? -res : res;
}

int main() {
    long long N = readLong();
    long long M = readLong();
    long long L = readLong();
    long long R = readLong();

    long long total = R - L + 1;
    long long E = total / 2 + ((total % 2 == 0 && L % 2 == 0) ? 1 : 0);
    long long O = total - E;

    long long answer;
    if ((N * M) % 2 == 1) {
        answer = fastExponentiation(E + O, N * M);
    } else {
        long long sum = (fastExponentiation(E + O, N * M) + fastExponentiation(E - O, N * M)) % mod;
        answer = (sum * modInverse(2)) % mod;
    }
    printf("%lld\n", answer);
    return 0;
}

